import subprocess
import sys

import pytest


def run_cli(seq):
    return subprocess.run(
        [sys.executable, "primer_tm.py", seq],
        capture_output=True,
        text=True,
    )


def parse(stdout, label):
    for line in stdout.splitlines():
        if line.startswith(label + ":"):
            return float(line.split(":", 1)[1])
    pytest.fail(f"label {label!r} not found in output:\n{stdout}")


def test_agctagctagctagctagct():
    r = run_cli("AGCTAGCTAGCTAGCTAGCT")
    assert r.returncode == 0, r.stderr
    assert parse(r.stdout, "Wallace") == pytest.approx(60.00)
    assert parse(r.stdout, "GC") == pytest.approx(51.78)


def test_atgc_wallace():
    r = run_cli("ATGC")
    assert r.returncode == 0, r.stderr
    assert parse(r.stdout, "Wallace") == pytest.approx(12.00)


@pytest.mark.parametrize("seq", ["ATGU", "atgxn", "ACGT ", "", "1234"])
def test_invalid_input(seq):
    r = run_cli(seq)
    assert r.returncode == 2
    assert r.stderr.strip() != ""


if __name__ == "__main__":
    sys.exit(pytest.main([__file__]))

